363	constexpr std::size_t find(string_view str, char_type c) noexcept {
364	#if defined(__clang__) && __clang_major__ < 9 && defined(__GLIBCXX__) || defined(_MSC_VER) && _MSC_VER < 1920 && !defined(__clang__)
365	// https://stackoverflow.com/questions/56484834/constexpr-stdstring-viewfind-last-of-doesnt-work-on-clang-8-with-libstdc
366	// https://developercommunity.visualstudio.com/content/problem/360432/vs20178-regression-c-failed-in-test.html
367	  constexpr bool workaround = true;
368	#else
369	  constexpr bool workaround = false;
370	#endif
371	
372	  if constexpr (workaround) {
373	    for (std::size_t i = 0; i < str.size(); ++i) {
374	      if (str[i] == c) {
375	        return i;
376	      }
377	    }
378	
379	    return string_view::npos;
380	  } else {
381	    return str.find(c);
382	  }
383	}
