419	template <typename L, typename R>
420	constexpr bool cmp_less(L lhs, R rhs) noexcept {
421	  static_assert(std::is_integral_v<L> && std::is_integral_v<R>, "magic_enum::detail::cmp_less requires integral type.");
422	
423	  if constexpr (std::is_same_v<L, bool> && std::is_same_v<R, bool>) {
424	    return static_cast<unsigned char>(lhs) < static_cast<unsigned char>(rhs);
425	  } else if constexpr (std::is_same_v<L, bool>) {
426	    return static_cast<R>(lhs) < rhs;
427	  } else if constexpr (std::is_same_v<R, bool>) {
428	    return lhs < static_cast<L>(rhs);
429	  } else if constexpr (std::is_signed_v<L> == std::is_signed_v<R>) {
430	    return lhs < rhs;
431	  } else if constexpr (std::is_signed_v<R>) {
432	    using C = std::common_type_t<std::make_unsigned_t<L>, std::make_unsigned_t<R>>;
433	    return rhs > 0 && static_cast<C>(lhs) < static_cast<C>(rhs);
434	  } else {
435	    using C = std::common_type_t<std::make_unsigned_t<L>, std::make_unsigned_t<R>>;
436	    return lhs < 0 || static_cast<C>(lhs) < static_cast<C>(rhs);
437	  }
438	}
