466	template <typename E>
467	constexpr auto MAGIC_ENUM_CALLING_CONVENTION n() noexcept {
468	  static_assert(is_enum_v<E>, "magic_enum::detail::n requires enum type.");
469	
470	  if constexpr (supported<E>::value) {
471	#if defined(MAGIC_ENUM_GET_TYPE_NAME_BUILTIN)
472	    constexpr auto name_ptr = MAGIC_ENUM_GET_TYPE_NAME_BUILTIN(E);
473	    constexpr auto name = name_ptr ? str_view{name_ptr, std::char_traits<char>::length(name_ptr)} : str_view{};
474	#elif defined(__clang__)
475	    str_view name;
476	    if constexpr (sizeof(__PRETTY_FUNCTION__) == sizeof(__FUNCTION__)) {
477	      static_assert(always_false_v<E>, "magic_enum::detail::n requires __PRETTY_FUNCTION__.");
478	      return str_view{};
479	    } else {
480	      name.size_ = sizeof(__PRETTY_FUNCTION__) - 36;
481	      name.str_ = __PRETTY_FUNCTION__ + 34;
482	    }
483	#elif defined(__GNUC__)
484	    auto name = str_view{__PRETTY_FUNCTION__, sizeof(__PRETTY_FUNCTION__) - 1};
485	    if constexpr (sizeof(__PRETTY_FUNCTION__) == sizeof(__FUNCTION__)) {
486	      static_assert(always_false_v<E>, "magic_enum::detail::n requires __PRETTY_FUNCTION__.");
487	      return str_view{};
488	    } else if (name.str_[name.size_ - 1] == ']') {
489	      name.size_ -= 50;
490	      name.str_ += 49;
491	    } else {
492	      name.size_ -= 40;
493	      name.str_ += 37;
494	    }
495	#elif defined(_MSC_VER)
496	    // CLI/C++ workaround (see https://github.com/Neargye/magic_enum/issues/284).
497	    str_view name;
498	    name.str_ = __FUNCSIG__;
499	    name.str_ += 40;
