1078	template <auto* GlobValues, typename Hash>
1079	constexpr auto calculate_cases(std::size_t Page) noexcept {
1080	  constexpr auto values = *GlobValues;
1081	  constexpr std::size_t size = values.size();
1082	
1083	  using switch_t = std::invoke_result_t<Hash, typename decltype(values)::value_type>;
1084	  static_assert(std::is_integral_v<switch_t> && !std::is_same_v<switch_t, bool>);
1085	  const std::size_t values_to = (std::min)(static_cast<std::size_t>(256), size - Page);
1086	
1087	  std::array<switch_t, 256> result{};
1088	  auto fill = result.begin();
1089	  {
1090	    auto first = values.begin() + static_cast<std::ptrdiff_t>(Page);
1091	    auto last = values.begin() + static_cast<std::ptrdiff_t>(Page + values_to);
1092	    while (first != last) {
1093	      *fill++ = hash_v<Hash>(*first++);
1094	    }
1095	  }
1096	
1097	  auto value = (std::numeric_limits<switch_t>::min)();
1098	  while (fill != result.end()) {
1099	    bool used = false;
1100	    for (std::size_t i = 0; i < values_to; ++i) {
1101	      if (result[i] == value) {
1102	        used = true;
1103	        break;
1104	      }
1105	    }
1106	    if (!used) {
1107	      *fill++ = value;
1108	    }
1109	    value = value == (std::numeric_limits<switch_t>::max)() ? (std::numeric_limits<switch_t>::min)() : static_cast<switch_t>(value + 1);
1110	  }
1111	
1112	  return result;
1113	}
