1135	template <auto* Arr, typename Hash>
1136	constexpr bool has_unique_hashes() noexcept {
1137	  using value_t = std::decay_t<decltype((*Arr)[0])>;
1138	  using hash_value_t = std::invoke_result_t<Hash, value_t>;
1139	  std::array<hash_value_t, Arr->size()> hashes{};
1140	  std::size_t size = 0;
1141	  for (auto elem : *Arr) {
1142	    hashes[size] = hash_v<Hash>(elem);
1143	    for (auto i = size++; i > 0; --i) {
1144	      if (hashes[i] < hashes[i - 1]) {
1145	        auto tmp = hashes[i];
1146	        hashes[i] = hashes[i - 1];
1147	        hashes[i - 1] = tmp;
1148	      } else if (hashes[i] == hashes[i - 1]) {
1149	        return false;
1150	      } else {
1151	        break;
1152	      }
1153	    }
1154	  }
1155	  return true;
1156	}
