1158	#define MAGIC_ENUM_CASE(val)                                                                                                  \
1159	  case cases[val]:                                                                                                            \
1160	    if constexpr ((val) + Page < size) {                                                                                      \
1161	      if (!pred(values[val + Page], searched)) {                                                                              \
1162	        break;                                                                                                                \
1163	      }                                                                                                                       \
1164	      if constexpr (CallValue == case_call_t::index) {                                                                        \
1165	        if constexpr (std::is_invocable_r_v<result_t, Lambda, std::integral_constant<std::size_t, val + Page>>) {             \
1166	          return detail::invoke_r<result_t>(std::forward<Lambda>(lambda), std::integral_constant<std::size_t, val + Page>{}); \
1167	        } else if constexpr (std::is_invocable_v<Lambda, std::integral_constant<std::size_t, val + Page>>) {                  \
1168	          MAGIC_ENUM_ASSERT(false && "magic_enum::detail::constexpr_switch wrong result type.");                                         \
1169	        }                                                                                                                     \
1170	      } else if constexpr (CallValue == case_call_t::value) {                                                                 \
1171	        if constexpr (std::is_invocable_r_v<result_t, Lambda, enum_constant<values[val + Page]>>) {                           \
1172	          return detail::invoke_r<result_t>(std::forward<Lambda>(lambda), enum_constant<values[val + Page]>{});               \
1173	        } else if constexpr (std::is_invocable_v<Lambda, enum_constant<values[val + Page]>>) {                                \
1174	          MAGIC_ENUM_ASSERT(false && "magic_enum::detail::constexpr_switch wrong result type.");                                         \
1175	        }                                                                                                                     \
1176	      }                                                                                                                       \
1177	      break;                                                                                                                  \
1178	    } else [[fallthrough]];
