1180	template <auto* GlobValues,
1181	          case_call_t CallValue,
1182	          std::size_t Page = 0,
1183	          typename Hash = constexpr_hash_t<typename std::decay_t<decltype(*GlobValues)>::value_type>,
1184	          typename BinaryPredicate = std::equal_to<>,
1185	          typename Lambda,
1186	          typename ResultGetterType>
1187	constexpr decltype(auto) constexpr_switch(
1188	    Lambda&& lambda,
1189	    typename std::decay_t<decltype(*GlobValues)>::value_type searched,
1190	    ResultGetterType&& def,
1191	    BinaryPredicate&& pred = {}) {
1192	  using result_t = std::invoke_result_t<ResultGetterType>;
1193	  using hash_t = std::conditional_t<has_unique_hashes<GlobValues, Hash>(), Hash, typename Hash::secondary_hash>;
1194	  static_assert(has_unique_hashes<GlobValues, hash_t>(), "magic_enum::detail::constexpr_switch duplicated hash found, please report it: https://github.com/Neargye/magic_enum/issues.");
1195	  constexpr auto values = *GlobValues;
1196	  constexpr std::size_t size = values.size();
1197	  constexpr auto cases = calculate_cases<GlobValues, hash_t>(Page);
1198	
1199	  switch (hash_v<hash_t>(searched)) {
1200	    MAGIC_ENUM_FOR_EACH_256(MAGIC_ENUM_CASE)
1201	    default:
1202	      if constexpr (size > 256 + Page) {
1203	        return constexpr_switch<GlobValues, CallValue, Page + 256, Hash>(std::forward<Lambda>(lambda), searched, std::forward<ResultGetterType>(def), std::forward<BinaryPredicate>(pred));
1204	      }
1205	      break;
1206	  }
1207	  return def();
