class case_insensitive {
  static constexpr char_type to_lower(char_type c) noexcept {
    return (c >= char_type{'A'} && c <= char_type{'Z'}) ? static_cast<char_type>(c + (char_type{'a'} - char_type{'A'})) : c;
  }

 public:
